/* ------------------------------------------------------------------------------------------
 * 7. npad contract (MEDIDO). Two producers set it:
 *    a) game C# InControl.NintendoSwitchInputDeviceManager$$.ctor (main+0x1dd6520):
 *       DebugPad.Initialize; Npad.Initialize; NpadJoy.SetHoldType(Horizontal=1);
 *       Npad.SetSupportedStyleSet(7); Npad.SetSupportedIdType({Handheld 0x20, No1 0});
 *       then CreateDevice(Handheld), CreateDevice(No1); UpdateInternalState reads
 *       GetStyleSet + GetState per device, Handheld first.
 *    b) Unity native InputSwitch (main+0x767750 / main+0x763964) using the header stub table:
 *       main+0x50 supported-style mask = 0 (=> SetSupportedNpadStyleSet skipped),
 *       main+0x60 players = 8 (=> SetSupportedNpadIdType(No1..No8, 8) from table main+0x2514a64),
 *       SetNpadJoyHoldType((stub main+0x70) & 1 = 0 => Vertical).
 *    The last call wins on the wire; the C# one runs at InControl manager creation, after the
 *    native one, so the effective contract is (a): styles 7, ids {Handheld, No1}, hold Horizontal.
 *    Host must publish BOTH Handheld (entry 8) and No1 (entry 0).
 * ------------------------------------------------------------------------------------------ */
#define T2_NPAD_ID_NO1                  0x00u
#define T2_NPAD_ID_HANDHELD             0x20u
#define T2_NPAD_HANDHELD_SHARED_ENTRY   8        /* hid shared-memory npad entry index for NpadId 0x20 (Momodora lesson) */
#define T2_NPAD_STYLE_FULLKEY           (1u << 0)
#define T2_NPAD_STYLE_HANDHELD          (1u << 1)
#define T2_NPAD_STYLE_JOYDUAL           (1u << 2)
#define T2_NPAD_STYLE_JOYLEFT           (1u << 3)
#define T2_NPAD_STYLE_JOYRIGHT          (1u << 4)
#define T2_NPAD_SUPPORTED_STYLES        (T2_NPAD_STYLE_FULLKEY | T2_NPAD_STYLE_HANDHELD | T2_NPAD_STYLE_JOYDUAL) /* = 7, MEDIDO immediate */
#define T2_NPAD_JOY_HOLD_HORIZONTAL     1u       /* MEDIDO immediate in the C# ctor */
#define T2_NPAD_UNITY_NATIVE_PLAYERS    8        /* MEDIDO header stub main+0x60 */
#define T2_NPAD_UNITY_NATIVE_STYLEMASK  0        /* MEDIDO header stub main+0x50 */
#define T2_NPAD_IDS_GAME_INIT           { T2_NPAD_ID_HANDHELD, T2_NPAD_ID_NO1 }   /* order of SetSupportedIdType */
#define T2_NPAD_IDS_GAME_COUNT          2
#define T2_NPAD_IDS_UNITY_INIT          { 0u, 1u, 2u, 3u, 4u, 5u, 6u, 7u }        /* native path, count 8 */
#define T2_NPAD_IDS_UNITY_COUNT         8

