/* ------------------------------------------------------------------------------------------
 * 8. Boot-path facts the forked layer must honour (MEDIDO in main unless noted).
 * ------------------------------------------------------------------------------------------ */
/* nninitStartup (main+0x6a5370) only calls QueryMemoryInfo + SetMemoryAllocatorForThreadLocal:
 * nn::mem::StandardAllocator, SetMemoryHeapSize, AllocateMemoryBlock and IsVirtualAddressMemoryEnabled
 * are NOT imported any more. Unity 6 heap = Baselib page allocator over nn::os::AllocateAddressRegion
 * + AllocateMemoryPages + SetMemoryPermission (svcMapPhysicalMemory 0x2c). VAMM is mandatory. */
#define T2_VAMM_REQUIRED                1
#define T2_SYSTEM_RESOURCE_SIZE         0x1000000u   /* NPDM, svcGetInfo 16 must report it */
#define T2_ADDRESS_SPACE_TYPE           3            /* 39-bit */
#define T2_KERNEL_VERSION_MAJOR         9
#define T2_KERNEL_VERSION_MINOR         1
/* Baselib bookkeeping reservation (main+0x1a03d8..0x1a0408, twice more in the IL2CPP copy):
 * size = ((MemoryInfo.total + 0xffff) >> 16) * 0x30 + 0xfff, page aligned -> 48 bytes per 64 KiB of
 * the memory the host DECLARES. Payload reservations are dynamic (Baselib_Memory_ReserveAddressRange). */
#define T2_VAMM_BOOKKEEPING_BYTES_PER_64K   0x30u
/* nv::InitializeGraphics size = boot.config nvn-graphics-firmware-memory (32) << 20. */
#define T2_NV_GRAPHICS_FIRMWARE_MEMORY  (32u << 20)
/* nn::ro: nnMain -> Baselib DynamicLibrary init -> nn::ro::Initialize() unconditionally
 * (ldr:ro IRoInterface 4), then OpenFile("rom:/.nrr/dynamic.nrr") which must FAIL (PathNotFound):
 * no NRR/NRO exists, so LoadModule (IRoInterface 0), RegisterModuleInfo (2), UnloadModule (1),
 * UnregisterModuleInfo (3), 10 are never sent. LookupSymbol is local (rtld module list). */
#define T2_RO_CMD_LOAD_NRO              0
#define T2_RO_CMD_UNLOAD_NRO            1
#define T2_RO_CMD_LOAD_NRR              2
#define T2_RO_CMD_UNLOAD_NRR            3
#define T2_RO_CMD_INITIALIZE            4    /* INFERIDO name (libnx RegisterProcessHandle); must succeed */
#define T2_RO_CMD_10                    10
#define T2_RO_DYNAMIC_NRR_PATH          "rom:/.nrr/dynamic.nrr"
#define T2_RO_DYNAMIC_NRR_FLAG_OFFSET   0x2ca31d8u  /* main byte: 1 = nrr registered (must stay 0) */
/* Thread contract: NPDM cores 0-2; main thread ideal 0 mask 1 prio 2; Baselib threads ideal 2
 * mask 7; NVN queue thread ideal 1 mask 7 prio 0; FMOD threads ideal 1; Enlighten mask 3 (dead). */
#define T2_NPDM_CORE_MASK               0x7u
#define T2_MAIN_THREAD_CORE_MASK        0x1u
#define T2_BASELIB_THREAD_IDEAL_CORE    2
#define T2_BASELIB_THREAD_CORE_MASK     0x7u
#define T2_GFX_THREADING_MODE           4    /* boot.config; table main+0x2c8a3b0 index 4 = kGfxThreadingModeClientWorkerNativeJobs */
/* Static SVC set of sdk+rtld (58, main and subsdk0 issue none): 18.3.2 minus 0x48/0x49. */
#define T2_SVC_STATIC_COUNT             58
#define T2_SVC_GONE_MAP_PHYSICAL_UNSAFE 0x48
#define T2_SVC_GONE_UNMAP_PHYSICAL_UNSAFE 0x49

#endif /* T2_HORIZON19_H */
